"""Shared fixtures for the tasks API test suite."""

from __future__ import annotations

from datetime import datetime, timezone, timedelta
from unittest.mock import Mock

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, TaskRepository
from tasks_api.service import TaskService
from tasks_api.app import create_app


# ── Deterministic clock ──────────────────────────────────────────────

FIXED_NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture
def fixed_now():
    """Return a fixed UTC datetime for deterministic tests."""
    return FIXED_NOW


@pytest.fixture
def clock(fixed_now):
    """Return a callable that always returns *fixed_now*."""
    return lambda: fixed_now


# ── Repositories ─────────────────────────────────────────────────────

@pytest.fixture
def in_memory_repo():
    return InMemoryTaskRepository()


@pytest.fixture
def mock_repo():
    return Mock(spec=TaskRepository)


# ── Service ──────────────────────────────────────────────────────────

@pytest.fixture
def service(in_memory_repo, clock):
    return TaskService(in_memory_repo, now=clock)


@pytest.fixture
def mock_service(mock_repo, clock):
    return TaskService(mock_repo, now=clock)


# ── Flask test client ────────────────────────────────────────────────

@pytest.fixture
def client(service):
    app = create_app(service=service)
    app.config["TESTING"] = True
    with app.test_client() as c:
        yield c


# ── Task factory helpers ─────────────────────────────────────────────

def make_task(
    id: int = 1,
    title: str = "Test task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at: datetime | None = None,
    completed_at: datetime | None = None,
    created_at: datetime | None = None,
    tags: list[Tag] | None = None,
) -> Task:
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        completed_at=completed_at,
        created_at=created_at or FIXED_NOW,
        tags=tags or [],
    )

